#!/usr/bin/env python3
# patch-158-E6: special orders + activity timeline + polish
"""
Final patch in the multi-asset arc. Closes the parity gap with the
legacy view and cleans up dead code from earlier patches.

What ships:

  - Special-order parts card. Shows pending/ordered/arrived parts
    tied to this appointment. Reuses the existing SoDrawer JS
    component and _drawer.blade.php partial — the "+ SO for this
    appointment" button opens the same drawer used in legacy.
    Includes the "block warning" amber border when status is
    in_progress and parts are unarrived.

  - Activity timeline (via system notes). The Notes card already
    receives system notes like "Bottom bracket added from inventory
    (qty 1)" automatically. E6 differentiates them visually:
    smaller, dimmed, with rounded background, labeled "Activity"
    rather than "System". The chronological order makes the Notes
    list double as an event log.

  - Polish:
    * Removed dead .ma-fallback-banner CSS (added in D, never used)
    * Removed dead .ma-coming-soon CSS (E1 replaced the placeholders
      but left the styles)

No controller changes. Reuses:
  - $specialOrdersForAppt + $soVendors (already passed by show())
  - tenant.special-orders._drawer partial (already exists)
  - SoDrawer JS helper (already loaded by drawer partial)
  - tenant.special-orders.show route (already exists)

After this, multi-asset view has full legacy parity. Feature is
ready to ship to launch customers.

Standalone Python. Idempotent. Single-file view patch.
"""
